import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const Cart = () => {
  const userId = sessionStorage.getItem("userId");
  const [items, setItems] = useState([]);

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/cart?user_id=${userId}`)
        .then((res) => res.json())
        .then((data) => setItems(data))
        .catch((err) => console.error("Error fetching cart:", err));
    }
  }, [userId]);

  const handleRemove = async (listingId) => {
    const res = await fetch(`${API_BASE_URL}/api/cart/${listingId}`, {
      method: "DELETE",
    });
    if (res.ok) {
      setItems((prev) => prev.filter((item) => item.listing_id !== listingId));
    }
  };

  const handleCheckout = async () => {
    const res = await fetch(`${API_BASE_URL}/api/cart/checkout`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user_id: userId }),
    });
    if (res.ok) {
      alert("Purchase complete!");
      setItems([]);
    } else {
      alert("Checkout failed");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="dashboard-main">
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>My Cart</h2>
        {items.length > 0 ? (
          <>
            <div className="item-grid">
              {items.map((item) => (
                <div className="item-card" key={item.id}>
                  <div className="image-placeholder">
                    {item.image ? (
                      <img src={item.image} alt={item.title} />
                    ) : (
                      <span>No Image</span>
                    )}
                  </div>
                  <h4>{item.title}</h4>
                  <p>{item.description}</p>
                  <p><strong>Condition:</strong> {item.condition}</p>
                  <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  <div className="item-actions">
                    <button className="edit-btn" onClick={() => handleRemove(item.listing_id)}>Remove</button>
                  </div>
                </div>
              ))}
            </div>
            <div style={{ textAlign: "center", marginTop: "24px" }}>
              <button className="buy-btn" onClick={handleCheckout}>Checkout</button>
            </div>
          </>
        ) : (
          <p style={{ textAlign: "center" }}>Your cart is empty.</p>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default Cart;
